<?php if($video):?><section class="project-video" aria-labelledby="video-title"><h2 id="video-title">ویدیوی پروژه</h2><video controls playsinline preload="metadata" <?php if(!empty($project['image'])&&media_path($project['image'])):?>poster="<?=e(media_path($project['image']))?>"<?php endif;?>><source src="<?=e($video)?>" type="<?=preg_match('~\.webm$~i',parse_url($video,PHP_URL_PATH))?'video/webm':'video/mp4'?>">مرورگر شما از پخش ویدیو پشتیبانی نمی‌کند. <a href="<?=e($video)?>">دریافت ویدیو</a></video></section><?php endif;?>
<?php if($gallery):?><section class="project-gallery" aria-labelledby="gallery-title"><div class="project-gallery-heading"><h2 id="gallery-title">گالری پروژه</h2><span><?=count($gallery)?> تصویر</span></div><div class="project-gallery-grid"><?php foreach($gallery as $i=>$media):?><figure><a class="gallery-image" href="<?=e(media_path($media['image']))?>" data-lightbox="<?=$i?>" data-caption="<?=e($media['caption']??'')?>" aria-label="نمایش تصویر <?=$i+1?>: <?=e($media['caption']??$project['title'])?>"><img src="<?=e(media_path($media['image']))?>" alt="<?=e(($media['caption']??'')?:$project['title'].'، تصویر '.($i+1))?>" loading="lazy"><span aria-hidden="true"><?=icon('plus')?></span></a><?php if(!empty($media['caption'])):?><figcaption><?=e($media['caption'])?></figcaption><?php endif;?></figure><?php endforeach;?></div></section>
<dialog id="gallery-dialog" aria-label="نمایش بزرگ تصویر پروژه"><button class="lightbox-close" aria-label="بستن تصویر"><?=icon('close')?></button><figure><img alt=""><figcaption></figcaption></figure><div class="lightbox-controls"><button data-lightbox-step="-1" aria-label="تصویر قبلی">→</button><span class="lightbox-counter" aria-live="polite"></span><button data-lightbox-step="1" aria-label="تصویر بعدی">←</button></div></dialog><script src="/assets/portfolio.js" defer></script><?php endif;?>
